const $=s=>document.querySelector(s),form=$('#vehicle-form');let configured=false,items=[],editing=null,photos=[],busy=false,comparables=[],requestGeneration=0,carouselBusy=false;
function message(text,error=false){$('#status').textContent=text;$('#status').classList.toggle('error',error);if(text)notify(text,{id:'action',type:error?'error':/guardad|listas|copiad|selección/i.test(text)?'success':'info'});else dismissNotice('action');}
async function api(path,method='GET',data){const r=await fetch('/api/'+path,{method,headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const result=await r.json();if(!r.ok)throw Error(result.error||'No se pudo completar la operación.');return result;}
const node=(tag,cls,text)=>{const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el;};
function screen(name){for(const id of ['auth','dashboard','editor','sales'])$('#'+id).hidden=id!==name;message('');}
function values(){return Object.fromEntries(new FormData(form));}
const makes=['Toyota','Ford','Nissan','Suzuki','Kia','Hyundai','Chevrolet','Volkswagen','Honda','Mazda','Mitsubishi','Jeep','BMW','Mercedes-Benz','Audi','Subaru','Changan','GWM','BYD'];
function datalist(input,options){const id='options-'+input.name;let list=document.getElementById(id);if(!list){list=node('datalist');list.id=id;document.body.append(list);}list.replaceChildren(...options.map(value=>{const o=node('option');o.value=value;return o;}));input.setAttribute('list',id);}
for(const [key,label,placeholder]of [['version','Versión / acabado','Según documentación de la unidad'],['city','Ciudad','Santa Cruz de la Sierra'],['country','País del mercado','Bolivia'],['condition','Condición','Nuevo, usado…'],['color','Color','Blanco'],['drive','Tracción','Según la configuración elegida']]){const l=node('label','',label),input=node('input');input.name=key;input.placeholder=placeholder;l.append(input);$('.fields').append(l);}
const identityFields=$('.fields');for(const key of ['make','year','name','version','engine','fuel','transmission','drive','type','mileage','condition','color','city','country','price','status'])identityFields.append(form.elements[key].closest('label'));datalist(form.elements.make,makes);for(const [key,opts]of Object.entries({condition:['Nuevo','Usado','Seminuevo'],city:['Santa Cruz de la Sierra','La Paz','Cochabamba','Sucre','Tarija','Oruro','Potosí','Trinidad','Cobija'],country:['Bolivia','Chile','Perú','Argentina','Paraguay','Brasil','Estados Unidos']}))datalist(form.elements[key],opts);
const priceInput=form.elements.price;priceInput.type='number';priceInput.min='0.01';priceInput.step='0.01';priceInput.placeholder='Ej. 60000';priceInput.closest('label').firstChild.textContent='Precio de venta (vacío: a consultar)';const currencyLabel=node('label','','Moneda'),currency=node('select');currency.name='currency';for(const [value,label]of [['','Selecciona moneda'],['BOB','Bs · Bolivianos'],['USD','US$ · Dólares']]){const option=node('option','',label);option.value=value;currency.append(option);}currencyLabel.append(currency);priceInput.closest('label').after(currencyLabel);
const featuredLabel=node('label','featured-field'),featured=node('input');featured.type='checkbox';featured.name='featured';featuredLabel.append(featured,node('span','','Mostrar en la ruleta del inicio · máximo 5 disponibles'));$('.fields').after(featuredLabel);
const helper=node('section','editor-help');helper.innerHTML='<strong>Una ficha precisa, paso a paso</strong><p id="spec-status"></p><div id="spec-source"></div><p id="spec-errors" role="status"></p><button type="button" id="write-description">Crear descripción con estos datos</button><span id="completion"></span>';form.prepend(helper);
const assistant=initVehicleAssistant({form,api,node,onChange:()=>invalidateResearch()});
function updateSuggestions(){const invalid=assistant.validate();$('#completion').textContent=`${['make','name','year','description'].filter(k=>form.elements[k].value.trim()).length}/4 datos principales · ${photos.length} fotos`;form.elements.currency.required=false;if(parseAmount(form.elements.price.value)>0&&!form.elements.currency.value)invalid.push('Selecciona la moneda del precio: Bs o Dólares.');return invalid;}
form.addEventListener('input',()=>{updateSuggestions();invalidateResearch();});
$('#write-description').onclick=()=>{const v=values();if(form.elements.description.value&&!confirm('¿Reemplazar la descripción actual por este borrador?'))return;form.elements.description.value=[`${v.make} ${v.name} ${v.version||''} ${v.year}`.replace(/\s+/g,' ').trim(),...Object.entries({Motor:v.engine,Transmisión:v.transmission,Tracción:v.drive,Combustible:v.fuel,Kilometraje:v.mileage,Color:v.color,Condición:v.condition,Ubicación:[v.city,v.country].filter(Boolean).join(', ')}).filter(([,val])=>val).map(([key,val])=>`${key}: ${val}.`),'Consulta los detalles y la disponibilidad con Torres Garage.'].join('\n');updateSuggestions();};
function photoList(){$('#photo-list').replaceChildren();photos.forEach((url,i)=>{const tile=node('div','photo'),img=node('img');img.src=url;img.alt='Foto '+(i+1);const cover=node('button','',i===0?'Portada':'Usar como portada');cover.type='button';cover.disabled=i===0;cover.onclick=()=>{photos.splice(i,1);photos.unshift(url);photoList();};const remove=node('button','','Quitar');remove.type='button';remove.onclick=()=>{photos.splice(i,1);photoList();};tile.append(img,cover,remove);$('#photo-list').append(tile);});updateSuggestions();}
function open(v){requestGeneration++;researchedSignature='';editing=v?.id||null;form.reset();for(const input of form.elements)if(input.name&&input.type!=='checkbox')input.value=v?.[input.name]||(input.name==='status'?'draft':input.name==='country'?'Bolivia':'');featured.checked=!!v?.featured;photos=[...(v?.photos||[])];comparables=structuredClone(v?.comparables||[]);const money=moneyParts(v||{});form.elements.price.value=money.amount??'';form.elements.currency.value=money.currency;assistant.open(v);$('#editor-title').textContent=v?'Editar vehículo':'Nuevo vehículo';screen('editor');window.scrollTo({top:0,behavior:'instant'});photoList();$('#research-results').replaceChildren();$('#automatic-prices').replaceChildren();$('#research-status').textContent='';searchLinks();$('#research').disabled=false;}
$('#new').onclick=()=>open();$('#cancel').onclick=()=>{requestGeneration++;if(!busy)screen('dashboard');};
$('#photos').onchange=async event=>{const files=[...event.target.files];if(files.length+photos.length>12){message('Máximo 12 fotos.',true);return;}busy=true;$('#save').disabled=true;try{for(const file of files){if(file.size>8*1024*1024)throw Error('Máximo 8 MB por fotografía.');const image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('No se pudo leer la foto.'));r.readAsDataURL(file);});photos.push((await api('admin/upload','POST',{image})).url);}photoList();message('Fotos listas. Guarda la ficha para conservarlas.');}catch(e){message(e.message,true);}finally{busy=false;$('#save').disabled=false;event.target.value='';}};
form.onsubmit=async event=>{event.preventDefault();if(busy)return;const errors=updateSuggestions();if(errors.length){message(errors.join(' '),true);return;}if(featured.checked&&form.elements.status.value!=='available'){message('Publica el vehículo como disponible para mostrarlo en la ruleta.',true);return;}busy=true;$('#save').disabled=true;try{await api('admin/inventory','POST',{...values(),priceAmount:parseAmount(form.elements.price.value)??'',torres360:tourEditor.capture(),videoLinks:videoEditor.capture(),privateFinance:operations.validate(),offerEnabled:operations.offerEnabled(),id:editing,featured:featured.checked,photos,comparables});await load();message('Vehículo guardado. Actualiza la vista cliente para ver los cambios.');}catch(e){message(e.message,true);}finally{busy=false;$('#save').disabled=false;}};
const tools=node('div','inventory-tools');tools.innerHTML='<label>Buscar inventario<input id="admin-search" type="search" placeholder="Marca, modelo, año…"></label><label>Estado<select id="admin-filter"><option value="active">Inventario activo</option><option value="available">Disponibles</option><option value="draft">Borradores</option><option value="sold">Vendidos</option></select></label><button type="button" id="export-inventory">Exportar inventario JSON</button>';$('#list').before(tools);const stats=node('div','admin-stats');tools.before(stats);const roulette=node('section','roulette-manager');roulette.innerHTML='<div><span class="eyebrow">EL ESCAPARATE DEL INICIO</span><h2>Tu ruleta, tu selección</h2><p>Escoge hasta 5 vehículos disponibles. El catálogo conserva todos los publicados.</p></div><strong id="roulette-count"></strong>';stats.after(roulette);
const scopeTabs=node('nav','inventory-scope-tabs');scopeTabs.setAttribute('aria-label','Inventario activo o vendido');for(const [scope,label]of [['active','Inventario activo'],['sold','Vehículos vendidos']]){const button=node('button','',label);button.type='button';button.dataset.scope=scope;button.onclick=()=>{$('#admin-filter').value=scope;filterRows();};scopeTabs.append(button);}tools.before(scopeTabs);const scopeEmpty=node('p','inventory-scope-empty');$('#list').after(scopeEmpty);function filterRows(){const q=$('#admin-search').value.toLowerCase(),status=$('#admin-filter').value;[...$('#list').children].forEach((row,i)=>{const v=items[i];if(v)row.hidden=!(row.textContent.toLowerCase().includes(q)&&matchesInventoryScope(v,status));});for(const button of scopeTabs.children){const sold=button.dataset.scope==='sold',count=items.filter(v=>sold?v.status==='sold':v.status!=='sold').length;button.textContent=(sold?'Vehículos vendidos':'Inventario activo')+' · '+count;button.setAttribute('aria-pressed',String(sold?status==='sold':status!=='sold'));}roulette.hidden=status==='sold';scopeEmpty.hidden=[...$('#list').children].some(row=>!row.hidden);scopeEmpty.textContent=status==='sold'?'No hay vehículos vendidos que coincidan con la búsqueda.':'No hay vehículos activos que coincidan con la búsqueda.';}$('#admin-search').oninput=filterRows;$('#admin-filter').onchange=filterRows;
async function toggleFeatured(v,button){if(carouselBusy)return;const ids=items.filter(x=>x.featured&&x.status==='available').map(x=>x.id);const next=v.featured?ids.filter(id=>id!==v.id):[...ids,v.id];if(next.length>5){message('Ya seleccionaste 5 vehículos. Quita uno antes de añadir otro.',true);return;}carouselBusy=true;button.disabled=true;try{await api('admin/carousel','POST',{ids:next});await load({preserveScroll:true});message('Selección de la ruleta guardada.');}catch(e){message(e.message,true);button.disabled=false;}finally{carouselBusy=false;}}
async function load({preserveScroll=false}={}){const savedY=window.scrollY;items=await api('admin/inventory');screen('dashboard');if(!preserveScroll)window.scrollTo({top:0,behavior:'instant'});$('#logout').hidden=false;$('#summary').textContent=`${items.length} vehículos · ${items.filter(v=>v.status==='available').length} publicados`;stats.replaceChildren(...[['Total',items.length],['Disponibles',items.filter(v=>v.status==='available').length],['Borradores',items.filter(v=>v.status==='draft').length],['Vendidos',items.filter(v=>v.status==='sold').length]].map(([label,count])=>{const box=node('div');box.append(node('strong','',count),node('span','',label));return box;}));$('#roulette-count').textContent=items.filter(v=>v.featured&&v.status==='available').length+' / 5';$('#list').replaceChildren();for(const v of items){const row=node('article','admin-row');if(v.photos?.[0]){const image=node('div','admin-thumbnail');if(v.exampleKey){image.classList.add('vehicle-image',v.exampleKey);image.setAttribute('role','img');image.setAttribute('aria-label',v.name);}else{const img=node('img');img.src=v.photos[0];img.alt=v.name;image.append(img);}row.append(image);}const copy=node('div'),title=node('h3','',v.make+' '+v.name),meta=node('p','',`${v.year} · ${{available:'Disponible',draft:'Borrador',sold:'Vendido'}[v.status]} · ${priceLabel(v)}`);copy.append(title,meta);const actions=node('div','actions'),feature=node('button','feature-button',v.featured&&v.status==='available'?'★ En la ruleta':'☆ Añadir a ruleta');feature.type='button';feature.setAttribute('aria-pressed',String(!!v.featured&&v.status==='available'));feature.disabled=v.status!=='available';feature.onclick=()=>toggleFeatured(v,feature);const edit=node('button','','Editar');edit.onclick=()=>open(v);const remove=node('button','','Eliminar');remove.onclick=async()=>{if(!confirm(`¿Eliminar ${v.make} ${v.name}?`))return;try{await api('admin/inventory','DELETE',{id:v.id});await load();}catch(e){message(e.message,true);}};actions.append(feature,edit,remove);row.append(copy,actions);$('#list').append(row);}if(!items.length)$('#list').textContent='Añade tu primer vehículo para empezar.';filterRows();if(preserveScroll)window.scrollTo({top:savedY,behavior:'instant'});}
$('#export-inventory').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(items,null,2)],{type:'application/json'})),a=node('a');a.href=url;a.download='torres-garage-inventario.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
const market=node('section','market-panel');market.innerHTML='<span class="eyebrow">PRECIOS CON IA</span><h2>Precio de referencia</h2><p>Consulta con los datos de esta ficha cuánto pedir en Bolivia: venta rápida, precio justo y venta lenta.</p><button type="button" id="research">Obtener los tres precios automáticamente</button><p id="research-status" role="status"></p><div id="search-links" class="search-links"></div><div id="automatic-prices"></div><div id="research-results"></div>';$('#save').before(market);
const signature=()=>JSON.stringify(Object.fromEntries(['make','name','year','version','engine','transmission','drive','fuel','city','country','condition','mileage','currency','type'].map(k=>[k,form.elements[k].value])));let researchedSignature='';function invalidateResearch(){searchLinks();if(researchedSignature&&researchedSignature!==signature()){$('#automatic-prices').replaceChildren();$('#research-status').textContent='La ficha cambió. Vuelve a calcular para usar estos datos.';requestGeneration++;researchedSignature='';comparables=[];$('#research').disabled=false;}}
function searchLinks(){$('#search-links').replaceChildren();}
const googlePricing=initGooglePricing({market,node,api,getData:values,validate:updateSuggestions,begin:()=>++requestGeneration,current:()=>requestGeneration,onQuery:()=>{researchedSignature=signature();},onUse:(price,currency)=>{operations.setPrice(price,currency);updateSuggestions();message('Precio elegido. Guarda el vehículo para publicarlo.');},notify});
$('#auth-form').onsubmit=async event=>{event.preventDefault();event.submitter.disabled=true;try{await api('admin/'+(configured?'login':'setup'),'POST',{password:$('#password').value});$('#password').value='';configured=true;await load();}catch(e){message(e.message,true);}finally{event.submitter.disabled=false;}};
$('#logout').onclick=async()=>{await api('admin/logout','POST',{});location.reload();};
const videoEditor=initVideoEditor({form,node});const tourEditor=initTourEditor({form,node,api,notify});const operations=initAdminOperations({form,node,getItems:()=>items,openVehicle:v=>open(v),notify});const baseOpen=open;open=v=>{baseOpen(v);operations.open(v);googlePricing.reset();videoEditor.open(v);tourEditor.open(v);};const baseLoad=load;load=async(options)=>{await baseLoad(options);operations.report(items);};
