try{const state=await api('admin/status');configured=state.configured;if(state.authenticated)await load();else if(!configured){$('#auth-title').textContent='Configura tu administrador';$('#auth-copy').textContent='Crea una contraseña de al menos 12 caracteres.';$('#password').minLength=12;$('#password').autocomplete='new-password';$('#auth-form button').textContent='Crear acceso';}}catch(e){message(e.message,true);}
